// sound_pass.dart - sound effect player for packs generated by soundpass.
//
// Setup:
//   1. flutter pub add audioplayers
//   2. Render the pack into assets/sfx and list the folder in pubspec.yaml:
//        flutter:
//          assets:
//            - assets/sfx/
//   3. Call `await SoundPass.init();` once at startup (e.g. in main() before runApp).
//
// Usage:
//   SoundPass.play('coin');
//   SoundPass.play('combo', level: combo - 1);   // ladder sounds
//   SoundPass.volume = 0.8;  SoundPass.muted = true;
//
// Flame games: this works as-is; or use flame_audio's FlameAudio.play() with the same files.
import 'dart:convert';
import 'dart:math';

import 'package:audioplayers/audioplayers.dart';
import 'package:flutter/foundation.dart';
import 'package:flutter/services.dart' show rootBundle;

class SoundPass {
  SoundPass._();

  /// Folder of the pack, as listed in pubspec.yaml.
  static const String folder = 'assets/sfx';
  static const Duration _repeatGuard = Duration(milliseconds: 30);

  static double volume = 1.0;
  static bool muted = false;

  static final Map<String, List<AudioPool>> _pools = {};
  static final Map<String, bool> _ladder = {};
  static final Map<String, int> _lastVariant = {};
  static final Map<String, DateTime> _lastPlayed = {};
  static final Random _rng = Random();
  static bool _ready = false;

  static Future<void> init({int voicesPerFile = 3}) async {
    if (_ready) return;
    final Map<String, dynamic> manifest =
        jsonDecode(await rootBundle.loadString('$folder/manifest.json'));
    // AudioCache resolves AssetSource paths relative to 'assets/'.
    final prefix = folder.startsWith('assets/') ? folder.substring('assets/'.length) : folder;
    for (final s in manifest['sounds'] as List) {
      final id = s['id'] as String;
      final files = List<String>.from(s['files'] as List);
      _ladder[id] = s['ladder'] == true;
      _pools[id] = [
        for (final f in files)
          await AudioPool.create(
            source: AssetSource('$prefix/$f'),
            maxPlayers: voicesPerFile,
          ),
      ];
    }
    _ready = true;
  }

  static bool has(String id) => _pools.containsKey(id);

  /// Play a sound by id. [level] picks the step of a ladder sound (combo, star).
  static Future<void> play(String id, {int level = 0, double volume = 1.0}) async {
    if (muted) return;
    final pools = _pools[id];
    if (pools == null || pools.isEmpty) {
      debugPrint('SoundPass: no sound "$id" (did you await SoundPass.init()?)');
      return;
    }
    final now = DateTime.now();
    final last = _lastPlayed[id];
    if (last != null && now.difference(last) < _repeatGuard) return;
    _lastPlayed[id] = now;

    int idx;
    if (_ladder[id] == true) {
      idx = level.clamp(0, pools.length - 1).toInt();
    } else {
      idx = _rng.nextInt(pools.length);
      if (pools.length > 1 && _lastVariant[id] == idx) idx = (idx + 1) % pools.length;
      _lastVariant[id] = idx;
    }
    await pools[idx].start(volume: (volume * SoundPass.volume).clamp(0.0, 1.0).toDouble());
  }
}
